# Indicator: NZA 2.1
# Parameters: $(start_periode), $(eind_periode)
# Ontologie: versie 2.1.0

PREFIX onz-g: <http://purl.org/ozo/onz-g#>
PREFIX onz-fin: <http://purl.org/ozo/onz-fin#>
PREFIX onz-pers: <http://purl.org/ozo/onz-pers#>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ( SUM(?verloonde_uren) AS ?indicator )
   {
    BIND ($(start_periode) AS ?start_periode)      
    BIND ($(eind_periode) AS ?eind_periode)

    ?overeenkomst 
        a onz-pers:ArbeidsOvereenkomst ;
        onz-g:startDatum ?overeenkomst_start .
    OPTIONAL {?overeenkomst onz-g:eindDatum ?overeenkomst_eind}

    FILTER (?overeenkomst_start <= ?eind_periode && (!BOUND(?overeenkomst_eind) || ?overeenkomst_eind >= ?start_periode))

    ?overeenkomst 
        onz-g:defines [
        a onz-fin:VerloondePeriode ;
        onz-g:startDatum ?verloon_start;
        onz-g:eindDatum ?verloon_eind ;
        onz-g:hasQuality [
            onz-g:hasQualityValue [
                onz-g:hasUnitOfMeasure onz-g:Uur ;
                onz-g:hasDataValue ?verloonde_uren
            ] ;
        ] ;
    ] .

    FILTER (?verloon_start <= ?eind_periode && (!BOUND(?verloon_eind) || ?verloon_eind >= ?start_periode))


  }

